(function(root){
 'use strict';
 // Original fan and owner arcs. Each sequel waits for a completed conversation and two league rounds.
 const fans=[
 ['문을 여는 사람들','선수들이 오기 전, 팬들이 구장 문을 열고 젖은 좌석을 닦는다. 한 팬이 손을 멈춘다. “우리는 남았는데, 선수들은 여기를 잠깐 거쳐 갈 곳으로 생각하나요?”','선수들에게 이 마음을 어떻게 전할까요?',['팬들이 왜 남았는지 먼저 듣고 전하겠습니다','응원에 걸맞은 경기로 답하겠다고 말하겠습니다','경기 뒤 서로 인사하는 일부터 챙기겠습니다'],['“잘하라는 말만 하러 온 건 아니에요. 우리를 기억했으면 해서요.”','“그 말, 기대해도 되겠죠?” 박수 뒤에 선수들에게 전해질 기대의 무게가 남는다.','“짧은 인사라도 직접 듣고 싶었어요. 결과가 나쁜 날에도요.”'],'어려운 날에도 같은 마음으로 만날 수 있습니까?',['팬들의 기대를 선수들과 함께 짊어지겠습니다','승리는 보장하지 않고 준비 과정을 설명하겠습니다'],['팬 대표가 선수들에게 전할 편지를 남긴다. 응원과 기대가 함께 담겼다.','“무조건 이긴다는 말보다 오래 들을 수 있겠네요.” 팬 대표가 의자를 밀어 넣는다.']],
 ['응원 뒤에 남은 질문','팬 대표가 접힌 편지를 다시 꺼낸다. 선수에게 힘이 되길 바란 말이 부담이 됐을지도 모른다고 걱정한다.','큰 응원이 부담스럽다는 선수에게 무엇을 전할까요?',['응원도 각자 다르게 받아들일 수 있다고 말하겠습니다','기대에서 도망치지 말자고 선수들을 독려하겠습니다','환호보다 다음 플레이 한 가지에 집중시키겠습니다'],['“모두 같은 표정으로 대답할 필요는 없겠네요.” 팬 대표도 자신의 말을 돌아본다.','“응원이 숙제처럼 느껴지지는 않았으면 해요.” 믿음과 걱정이 함께 남는다.','“우리가 부를 노래와 선수가 할 일을 구분하자는 거군요.”'],'다음 응원에서는 어떤 메시지를 중심에 둘까요?',['다시 일어설 힘을 주는 기대를 함께 전하죠','결과를 재촉하기보다 다음 시도를 응원하죠'],['팬 대표는 응원 문구를 소리 내 읽는다. 힘을 얻는 선수도 긴장하는 선수도 있을 것이다.','편지의 마지막 문장이 바뀐다. “실수 다음에도 공을 받으러 가 주세요.”']],
 ['다시 부르는 노래','훈련이 끝나자 팬 몇 명이 짧게 구단 노래를 부른다. 팬 대표는 박수가 잦아들 때까지 기다렸다가 감독에게 다가온다.','우리와 선수 사이에 어떤 관계가 남았으면 좋겠습니까?',['서운한 날에도 서로의 이야기를 들을 수 있는 관계','높은 기대를 함께 감당하며 도전하는 관계','매 경기 지킬 작은 행동으로 믿음을 쌓는 관계'],['“응원을 그만둘까 고민한 날도 말해도 되겠네요.”','“우리도 말만 크게 하지 않을게요. 어려운 날에도 자리를 지키겠습니다.”','“이름을 기억하고 인사하는 일부터 다시 시작하죠.”'],'선수들에게 마지막으로 어떤 마음을 전할까요?',['이 응원을 책임감으로 받아들이자','응원을 느끼되 결과의 부담은 나누자'],['선수단에 응원의 뜻이 전달된다. 책임감이 동력이 될지 압박이 될지는 선수마다 다르다.','감독은 응원과 성적의 책임을 같은 말로 묶지 않는다. 선수들이 각자의 속도로 고개를 끄덕인다.']]
 ];
 const board=[
 ['낡은 장부의 여백','구단주가 빛바랜 경기장 사진과 운영 장부를 나란히 놓는다. “선수들은 더 좋은 환경을 원하고, 팬들은 빨리 돌아가길 원해요. 감독님에게는 무엇부터 부탁해야 할까요?”','선수단에 전달할 방향을 골라 주세요.',['선수들이 지금 감당하는 어려움부터 듣겠습니다','높은 목표를 숨기지 않고 도전하겠습니다','이번 경기에서 지킬 준비 기준부터 세우겠습니다'],['“장부에 없는 이야기도 들어야겠군요.” 구단주가 펜을 내려놓는다.','“그 자신감이 필요했어요. 다만 모두가 같은 무게로 듣지는 않을 겁니다.”','“결과만 재촉하기 전에 무엇을 준비했는지 묻겠습니다.”'],'선수들에게 성적에 대한 기대를 어떻게 설명할까요?',['목표의 책임을 함께 지겠다고 말하겠습니다','목표는 설명하되 한 경기 결과는 보장하지 않겠습니다'],['구단주의 기대가 선수단에 전달된다. 도전을 반기는 선수와 부담을 느끼는 선수가 갈린다.','구단주는 다음 면담 날짜를 적는다. “숫자뿐 아니라 준비 이야기도 듣겠습니다.”']],
 ['성과표 앞의 빈 의자','구단주는 성적표를 펼쳐 놓고도 바로 묻지 않는다. “선수들을 대신해서 감독님만 모든 말을 듣고 있는 건 아닌가요?”','구단주에게 어떤 역할을 부탁할까요?',['선수들이 느끼는 부담을 함께 들어 주세요','우리 목표를 믿는다는 말을 분명히 해 주세요','전술과 선발은 감독이 설명하도록 맡겨 주세요'],['“걱정을 듣는 것과 기준을 낮추는 것은 다르겠군요.”','“믿는다는 말이 압박으로 들릴 수도 있다는 점도 생각하겠습니다.”','“역할을 섞어 선수들을 혼란스럽게 만들지는 않겠습니다.”'],'면담 뒤 선수단에 무엇을 전할까요?',['구단이 믿는 만큼 책임 있게 도전하자','한 번의 결과로 너희 전부를 판단하지 않는다'],['선수들은 구단의 기대를 듣는다. 몇몇은 자세를 고치고, 몇몇은 조용히 숨을 고른다.','구단주의 말은 감독을 거쳐 전달된다. 결과와 선수의 가치를 같은 것으로 말하지 않는다.']],
 ['보고서 밖에 남은 이름','구단주가 보고서 마지막 장을 넘긴다. 출전이 적었던 선수와 원정을 따라온 팬의 이름이 메모돼 있다. “이 사람들도 우리 구단의 성적표에 들어가야겠죠?”','이번 여정에서 지키고 싶은 것을 말해 주세요.',['숫자 뒤에 있는 사람들의 이야기를 잊지 않겠습니다','우리가 어디까지 도전하는 팀인지 보여주겠습니다','좋은 준비를 반복하는 구단으로 만들겠습니다'],['“감독님이 오래 기억하는 이름이 구단에도 남겠군요.”','“기대는 계속 커질 겁니다. 선수들이 감당하는 속도도 봐 주세요.”','“좋은 날만 가능한 방식이 아니라는 걸 다음에도 확인하죠.”'],'다음 경기를 앞둔 선수들에게 어떤 기준을 남길까요?',['구단 전체의 기대를 품고 도전하자','각자 준비한 역할에 집중하고 부담은 나누자'],['보고서는 닫혔지만 기대는 남았다. 선수들은 저마다 다른 방식으로 그 말을 받아들인다.','구단주는 감독을 배웅한다. 선수단에는 다음 경기에 필요한 말만 차분히 전해진다.']]
 ];
 function events(s,year){const league=year===s.year?s.league:s.history?.find(h=>h.year===year);if(league?.rules!=='five-tier')return [];const total=league.division===1?38:46,records=s.clubStory?.records||[],out=[];
  for(const [prefix,relation,start,rows] of [['fan-voices','fans',1,fans],['owner-trust','board',3,board]]){let round=start;for(let i=0;i<rows.length;i++){const key=prefix+'-'+(i+1),parent=i?records.find(r=>r.event===year+':'+prefix+'-'+i&&r.step===1):null,previous=i?records.find(r=>r.event===year+':'+prefix+'-'+i&&r.step===0):null;if(i){if(!parent||!previous)break;round=parent.atRound+2;}if(round>total)break;const [title,scene,question,options,replies,followQuestion,followOptions,finalReplies]=rows[i],memory=parent?' 지난번 “'+rows[i-1][6][parent.choice==='commit'?0:1]+'”라는 답을 기억하고 있다.':'';out.push({key,round,relation,speaker:relation==='fans'?'팬 대표':'구단주',title,scene:scene+memory,question,options,replies,followQuestion,followOptions,finalReplies});}}
  return out;
 }
 const api={events};root.StoryCommunity=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
